## 3. `index.js` — O código principal

```javascript
require('telegraf')({ token: process.env.BOT_TOKEN });

const bot = new TelegramBot();

// Estado global para armazenar timers ativos
const timersAtivos = new Map(); // idUsuario => timerId

// ------------------------------------------------------------------
// Comandos do Bot
// ------------------------------------------------------------------

bot.start((msgUpdate, callback) => {
  const msg = msgUpdate.message;
  const user = msg.from.user_id;

  const reply = `👋 Olá ${msg.first_name || msg.username ? `${msg.first_name} (${msg.username})` : 'usuário'}!

Como posso ajudar?

📅 /startcount   → Iniciar contagem regressiva
🛑 /stopcount    → Parar uma contagem ativa
❓ /help         → Ver este menu`;

  callback({ replyToMessage: msg, reply: reply });
});

// ------------------------------------------------------------------
// /startcount - Inicia a contagem regressiva
// ------------------------------------------------------------------
bot.command('startcount', async (msgUpdate) => {
  const msg = msgUpdate.message;
  const userId = msg.from.user_id;

  // Valida formato HH:MM
  const input = msg.text.trim().toLowerCase();
  const match = input.match(/^(\d{2}):(\d{2})$/);

  if (!match) {
    const err = `⚠️ Formato inválido!\nUse HH:MM (ex: 02:30)\n\nExemplo: /startcount 02:30`;
    await msg.chat.sendText(err, { parse_mode: 'Markdown' });
    return;
  }

  const horas = parseInt(match[1], 10);
  const minutos = parseInt(match[2], 10);

  // Validação básica
  if (horas < 0 || horas > 23 || minutos < 0 || minutos > 59) {
    await msg.chat.sendText(
      `⚠️ Valor inválido! Horas devem ser de 00 a 23 e minutos de 00 a 59.\n\nVocê digitou: ${input}`,
      { parse_mode: 'Markdown' }
    );
    return;
  }

  // Se já tem contagem ativa para esse usuário, avisa
  if (timersAtivos.has(userId)) {
    await msg.chat.sendText(
      `⚠️ Já existe uma contagem ativa para você!\n\nPará ela primeiro com */stopcount|`,
      { parse_mode: 'Markdown' }
    );
    return;
  }

  // Tempo total em milissegundos (a partir de agora)
  const totalMs = (horas * 60 * 1000) + (minutos * 1000);

  console.log(`✅ Iniciada contagem para ${userId}: ${horas}h${minutos.toString().padStart(2, '0')} (${totalMs}ms)`);

  // Cria função de tick
  const tickInterval = setInterval(() => {
    const remainingMs = totalMs - Date.now();

    // Converte para HH:MM:SS
    const segs = Math.floor(remainingMs / 1000);
    const h = Math.floor(segs / 3600);
    const m = Math.floor((segs % 3600) / 60);
    const s = segs % 60;

    const str = `${h.toString().padStart(2, '0')}h ${m.toString().padStart(2, '0')}m ${s.toString().padStart(2, '0')}s`;

    // Se acabou
    if (remainingMs <= 0) {
      clearInterval(tickInterval);
      timersAtivos.delete(userId);

      await msg.chat.sendText(
        `🎉 Tempo esgotado! Você configurou **${horas}h${minutos.toString().padStart(2, '0')}**.\n\nAguarde a próxima contagem.\n\n💡 Use */stopcount| para cancelar outras.",
        { parse_mode: 'Markdown' }
      );
      return;
    }

    // Envia mensagem a cada 30 segundos (ajuste conforme quiser)
    const INTERVALO_MS = 30_000;
    if (Date.now() % INTERVALO_MS < remainingMs) {
      await msg.chat.sendText(
        `⏱️ Faltam **${str}** para terminar!\n\nConfiguração: **${horas}h${minutos.toString().padStart(2, '0')}**\nID da sessão: ${userId}`
      );
    }
  }, 1000); // atualiza a cada segundo

  // Guarda referência do timer (associada ao userId)
  timersAtivos.set(userId, { intervalId: tickInterval, horas, minutos });

  const confirmacao = `✅ Contagem iniciada! Vai rodar por **${horas}h${minutos.toString().padStart(2, '0')}** e avisará a cada 30 segundos.\n\nCancele com */stopcount|`;

  await msg.chat.sendText(confirmacao, { parse_mode: 'Markdown' });
});

// ------------------------------------------------------------------
// /stopcount - Para contagem ativa
// ------------------------------------------------------------------
bot.command('stopcount', async (msgUpdate) => {
  const userId = msgUpdate.message.from.user_id;
  const entry = timersAtivos.get(userId);

  if (!entry) {
    await msg.chat.sendText('⚠️ Não há nenhuma contagem ativa para você.\n\nUse */startcount| para iniciar uma nova.');
    return;
  }

  clearInterval(entry.intervalId);
  timersAtivos.delete(userId);

  await msg.chat.sendText(
    `🛑 Contagem parada! Obrigado.\n\nSe precisar recomeçar, use */startcount|`
  );
});

// ------------------------------------------------------------------
// /help
// ------------------------------------------------------------------
bot.command('help', async () => {
  const helpText = `🤖 **Comandos disponíveis:**

📌 */startcount <HH:MM>*  — Inicie uma contagem regressiva. Ex: */startcount 02:30*
📌 */stopcount*          — Pare uma contagem ativa
📌 */help*               — Este menu

👉 A contagem envia avisos a cada **30 segundos**.
👉 O formato é **HH:MM** (ex: 01:00, 00:30).

Qualquer dúvida, me chame! 🚀`;

  await msg.chat.sendText(helpText, { parse_mode: 'Markdown' });
});

// ------------------------------------------------------------------
// Lógica central do Telegraf
// ------------------------------------------------------------------
bot.telegram.on('message', async (msgUpdate) => {
  const text = msgUpdate.message.text;

  // Se for comando iniciado com "/"
  if (text.startsWith('/')) {
    const cmd = text.slice(1).trim().toLowerCase();
    try {
      switch (cmd) {
        case 'startcount':
          // Extrai HH:MM do restante da string se houver mais texto
          const resto = text.slice(text.indexOf(' ') + 1).trim();
          await bot.startcount(resto || undefined);
          break;
        case 'stopcount':
          await bot.stopcount();
          break;
        case 'help':
          await bot.help();
          break;
        default:
          await msg.chat.sendText(
            `❌ Comando desconhecido: */${cmd}|*\n\nUse */help| para ver a lista.`
          );
      }
    } catch (err) {
      console.error('Erro no comando:', err);
      await msg.chat.sendText('⚠️ Erro interno ao processar seu comando.');
    }
    return;
  }

  // Mensagens normais (opcional: respostas úteis)
  if (text === '/oi') {
    await msg.chat.sendText('👋 Oi! Como posso ajudar?');
  }
});

// Boot
console.log('🚀 Bot rodando...');
bot.start();
```

