  .cal-day:hover{border-color:var(--accent)}
  .cal-day.today{border-color:var(--accent);background:rgba(59,130,246,.15)}
  .cal-day.past{opacity:.5}
  .cal-day.event{background:rgba(34,197,94,.15);border-color:var(--success)}
  .cal-day.urgent{background:rgba(239,68,68,.15);border-color:var(--danger)}
  .cal-label{font-size:10px;color:var(--text-muted);margin-bottom:4px;text-transform:uppercase}
  /* Animations */
  .fade-in{animation:fadeIn .3s ease forwards}
  @keyframes fadeIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}
  /* Scrollbar */
  ::-webkit-scrollbar{width:6px}
  ::-webkit-scrollbar-track{background:transparent}
  ::-webkit-scrollbar-thumb{background:#475569;border-radius:3px}
  /* Responsive */
  @media(max-width:768px){
    .sidebar{width:100%;position:fixed;top:0;left:0;bottom:0;z-index:800}
    .sidebar.collapsed{transform:translateX(-100%)}
    .main{margin-left:0}
    .main-content{width:100%}
    .tab-bar{flex-wrap:wrap}
    .form-row{flex-direction:column}
  }
</style>
</head>
<body>

<!-- ================= SIDEBAR ================= -->
<aside class="sidebar" id="sidebar">
  <div class="sidebar-header">
    <div class="logo"><i class="fas fa-scale-balanced"></i> MI<span>S</span>SY</div>
