  </div>
  <nav class="nav-links" id="navLinks">
    <div class="nav-item active" data-tab="dashboard">
      <i class="nav-icon fas fa-home"></i> Painel
    </div>
    <div class="nav-item" data-tab="clientes">
      <i class="nav-icon fas fa-user-tag"></i> Clientes
    </div>
    <div class="nav-item" data-tab="processos">
      <i class="nav-icon fas fa-file-pdf"></i> Processos
    </div>
    <div class="nav-item" data-tab="documentos">
      <i class="nav-icon fas fa-folder-open"></i> Documentos
    </div>
    <div class="nav-item" data-tab="agenda">
      <i class="nav-icon fas fa-calendar-days"></i> Agenda
    </div>
    <div class="nav-item" data-tab="financas">
      <i class="nav-icon fas fa-money-bill-alt"></i> Finanças
    </div>
    <div class="nav-item" data-tab="tarefas">
      <i class="nav-icon fas fa-check-square"></i> Tarefas
    </div>
    <div class="nav-item" data-tab="colaboradores">
      <i class="nav-icon fas fa-users"></i> Colaboradores
    </div>
    <div class="nav-item" data-tab="intimacoes">
      <i class="nav-icon fas fa-bell"></i> Intimações
    </div>
    <div class="nav-item" data-tab="backup">
      <i class="nav-icon fas fa-cloud-download"></i> Backup
    </div>
    <div class="nav-item" data-tab="config">
      <i class="nav-icon fas fa-cog"></i> Configurações
    </div>
  </nav>
  <div class="user-area">
    <div class="avatar">AD</div>
    <div>
      <div style="font-size:14px;font-weight:600">Ana Duarte</div>
      <div class="small">Sócia Gestora</div>
    </div>
  </div>
</aside>

<!-- ================= MAIN ================= -->
<main class="main">
  <div class="main-content">
    <!-- Topbar -->
    <header class="topbar">
      <div class="topbar-left">
        <button class="btn-sm" onclick="toggleSidebar()">
          <i class="fas fa-bars"></i>
        </button>
        <h2 id="pageTitle" class="fade-in">Painel Geral</h2>
      </div>
      <div class="tab-bar">
        <button class="tab active" data-tab="dashboard" onclick="switchTab('dashboard')">
          <i class="fas fa-home mr-2"></i>Painel
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="clientes" onclick="switchTab('clientes')">
          <i class="fas fa-user-tag mr-2"></i>Clientes
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="processos" onclick="switchTab('processos')">
          <i class="fas fa-file-pdf mr-2"></i>Processos
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="documentos" onclick="switchTab('documentos')">
          <i class="fas fa-folder-open mr-2"></i>Documentos
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="agenda" onclick="switchTab('agenda')">
          <i class="fas fa-calendar mr-2"></i>Agenda
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="financas" onclick="switchTab('financas')">
          <i class="fas fa-coins mr-2"></i>Finanças
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="tarefas" onclick="switchTab('tarefas')">
          <i class="fas fa-tasks mr-2"></i>Tarefas
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="colaboradores" onclick="switchTab('colaboradores')">
          <i class="fas fa-users-cogs mr-2"></i>Colaboradores
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="intimacoes" onclick="switchTab('intimacoes')">
          <i class="fas fa-envelope mr-2"></i>Intimações
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="backup" onclick="switchTab('backup')">
          <i class="fas fa-hard-platter mr-2"></i>Backup
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="config" onclick="switchTab('config')">
          <i class="fas fa-settings mr-2"></i>Config
          <span class="tab-dot"></span>
        </button>
      </div>
      <div class="header-actions">
        <button class="btn-sm" onclick="openNotifications()">
          <i class="fas fa-bell"></i>
          <span id="notifCount" class="badge badge-blue" style="display:inline-block;margin-left:4px;width:18px;height:18px;text-align:center;line-height:18px">0</span>
        </button>
        <button class="btn-sm btn-primary" onclick="openModal('addClient')">
          <i class="fas fa-plus"></i> Novo Item
        </button>
        <div class="avatar" style="width:32px;height:32px">AD</div>
      </div>
    </header>

    <!-- Conteúdo dinâmico -->
    <div id="appContent" class="flex-1 overflow-auto pb-20">

      <!-- ============ DASHBOARD ============ -->
      <section id="tab-dashboard" class="fade-in space-y-6">
        <div class="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold">R$ <span id="dashTotalReceita">0,00</span></div>
                <div class="text-xs text-green-400 mt-1">↑ 12% no mês</div>
              </div>
              <i class="fas fa-dollar-sign text-2xl text-accent opacity-70"></i>
            </div>
          </div>
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold"><span id="dashTotalClientes">0</span> clientes</div>
                <div class="text-xs text-blue-400 mt-1">ativos hoje</div>
              </div>
              <i class="fas fa-users text-2xl text-accent opacity-70"></i>
            </div>
          </div>
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold"><span id="dashTotalProcessos">0</span> processos</div>
                <div class="text-xs text-yellow-400 mt-1">em andamento</div>
              </div>
              <i class="fas fa-law-contract text-2xl text-warning opacity-70"></i>
            </div>
          </div>
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold"><span id="dashPendentes">0</span> pendentes</div>
                <div class="text-xs text-red-400 mt-1">próximos 7 dias</div>
              </div>
              <i class="fas fa-clock text-2xl text-red-400 opacity-70"></i>
            </div>
          </div>
        </div>
        <div class="card p-5">
          <h3 class="text-lg font-semibold mb-4">Últimas Intimações</h3>
          <div id="dashboardRecentes" class="space-y-3 max-h-64 overflow-y-auto">
            <p class="small text-center text-text-muted">Nenhuma intimação recente.</p>
          </div>
        </div>
        <div class="card p-5">
          <h3 class="text-lg font-semibold mb-4">Atalhos Rápidos</h3>
          <div class="grid grid-cols-2 gap-3">
            <button class="btn-sm" onclick="openModal('addClient')">Novo Cliente</button>
            <button class="btn-sm" onclick="openModal('addProcess')">Novo Processo</button>
            <button class="btn-sm" onclick="importIntimacoes()">Importar Intimações</button>
            <button class="btn-sm" onclick="generateBackup()">Gerar Backup</button>
          </div>
        </div>
      </section>

      <!-- ============ CLIENTES ============ -->
      <section id="tab-clientes" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">🧑 Clientes</h2>
            <button class="btn-sm btn-primary" onclick="openModal('addClient')">
              <i class="fas fa-plus"></i> Novo Cliente
            </button>
          </div>

          <div class="form-row mb-4">
            <input type="text" id="searchClients" placeholder="Buscar clientes..." class="input-field w-1/3" oninput="filterClients()">
            <select id="filterStatusClients" class="input-field w-1/5">
              <option value="">Todos</option>
              <option value="ativo">Ativo</option>
              <option value="inativo">Inativo</option>
            </select>
          </div>

          <div id="clientsTable" class="overflow-x-auto">
            <table>
              <thead><tr>
                <th>Nome</th><th>Email</th><th>Cidade</th><th>Status</th><th>Data Cadastro</th><th>Ações</th>
              </tr></thead>
              <tbody id="clientsBody"></tbody>
            </table>
          </div>
        </div>
      </section>

      <!-- ============ PROCESSOS ============ -->
      <section id="tab-processos" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">⚖️ Processos</h2>
            <button class="btn-sm btn-primary" onclick="openModal('addProcess')">
              <i class="fas fa-plus"></i> Novo Processo
            </button>
          </div>
          <div class="form-row mb-4">
            <input type="text" id="searchProcesses" placeholder="Buscar processos..." class="input-field w-1/3" oninput="filterProcesses()">
          </div>
          <div id="processesTable" class="overflow-x-auto">
            <table>
              <thead><tr>
                <th>Número</th><th>Cliente</th><th>Classe</th><th>Status</th><th>Data Abertura</th><th>Valor</th><th>Ações</th>
              </tr></thead>
              <tbody id="processesBody"></tbody>
            </table>
          </div>
        </div>
      </section>

      <!-- ============ DOCUMENTOS ============ -->
      <section id="tab-documentos" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">📄 Documentos</h2>
            <button class="btn-sm btn-primary" onclick="openModal('addDoc')">
              <i class="fas fa-plus"></i> Novo Documento
            </button>
          </div>
          <div id="docsTable" class="overflow-x-auto">
            <table>
              <thead><tr>
                <th>Título</th><th>Tipo</th><th>Processo</th><th>Cliente</th><th>Status</th><th>Data</th><th>Ações</th>
              </tr></thead>
              <tbody id="docsBody"></tbody>
            </table>
          </div>
        </div>
      </section>

      <!-- ============ AGENDA ============ -->
      <section id="tab-agenda" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">📅 Agenda da Semana</h2>
            <button class="btn-sm btn-primary" onclick="openModal('addCompromisso')">
              <i class="fas fa-plus"></i> Novo Compromisso
            </button>
          </div>
          <div class="mb-4 flex gap-2">
            <button class="btn-sm" onclick="setWeek(0)">Segunda</button>
            <button class="btn-sm" onclick="setWeek(1)">Terça</button>
            <button class="btn-sm" onclick="setWeek(2)">Quarta</button>
            <button class="btn-sm" onclick="setWeek(3)">Quinta</button>
            <button class="btn-sm" onclick="setWeek(4)">Sexta</button>
          </div>
          <div id="calGrid" class="cal-grid"></div>
        </div>
      </section>

      <!-- ============ FINANÇAS ============ -->
      <section id="tab-financas" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">💸 Finanças</h2>
            <div class="flex gap-2">
              <button class="btn-sm btn-success" onclick="openModal('addExpense')">
                <i class="fas fa-plus"></i> Lançamento
              </button>
              <button class="btn-sm" onclick="showBalance()">Ver Saldo</button>
            </div>
          </div>

          <!-- Resumo -->
          <div class="grid grid-cols-3 gap-3 mb-6">
            <div class="card p-4 bg-gradient-to-r from-indigo-900 to-slate-800">
              <div class="text-xs text-slate-400">Saldo Total</div>
              <div class="text-2xl font-bold" id="saldoTotal">R$ 0,00</div>
            </div>
            <div class="card p-4 bg-green-900/30 border-green-700">
              <div class="text-xs text-green-400">Entradas</div>
              <div class="text-2xl font-bold text-green-400" id="totalEntradas">R$ 0,00</div>
            </div>
            <div class="card p-4 bg-red-900/30 border-red-700">
              <div class="text-xs text-red-400">Saídas</div>
              <div class="text-2xl font-bold text-red-400" id="total saidas">R$ 0,00</div>
            </div>
          </div>

          <div class="form-row mb-4">
            <select id="typeTx" class="input-field w-1/4">
              <option value="entrada">Entrada</option>
              <option value="saida">Saída</option>
            </select>
            <input type="text" id="txDesc" placeholder="Descrição" class="input-field flex-1">
            <input type="currency" id="txValue" placeholder="Valor" class="input-field w-1/4">
            <select id="txTipo" class="input-field w-1/4">
              <option value="cliente">Cliente</option>
              <option value="taxa">Taxa Judicial</option>
              <option value="custo">Custo</option>
              <option value="receita">Receita</option>
            </select>
          </div>
          <button class="btn-sm btn-primary w-full" onclick="addTransaction()">Adicionar Lançamento</button>

          <div class="overflow-x-auto mt-6">
            <table>
              <thead><tr>
                <th>Data</th><th>Descrição</th><th>Tipo</th><th>Valor</th><th>Cliente</th><th>Status</th><th>Ações</th>
              </tr></thead>
              <tbody id="transactionsBody"></tbody>
            </table>
          </div>
        </div>
      </section>

      <!-- ============ TAREFAS ============ -->
      <section id="tab-tarefas" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">✅ Tarefas</h2>
            <button class="btn-sm btn-primary" onclick="openModal('addTask')">
              <i class="fas fa-plus"></i> Nova Tarefa
            </button>
          </div>
          <div class="form-row mb-4">
            <input type="text" id="taskTitle" placeholder="Título da tarefa" class="input-field flex-1">
            <select id="taskType" class="input-field w-1/5">
              <option value="">Tipo</option>
              <option>Prazo processual</option>
              <option>Contato cliente</option>
              <option>Elaborar peça</option>
              <option>Protocolo</option>
              <option>Financeiro</option>
            </select>
          </div>
          <div class="mb-4">
            <label class="label">Filtrar por:</label>
            <div class="flex gap-2">
              <button class="btn-sm" onclick="filterTasks('all')">Todas</button>
              <button class="btn-sm bg-yellow-600/20 text-yellow-300 border border-yellow-600" onclick="filterTasks('pendente')">Pendente</button>
              <button class="btn-sm bg-green-600/20 text-green-300 border border-green-600" onclick="filterTasks('concluido')">Concluída</button>
            </div>
          </div>
          <div id="tasksList" class="space-y-2 max-h-[420px] overflow-y-auto">
            <!-- tasks rendered here -->
          </div>
        </div>
      </section>

      <!-- ============ COLABORADORES ============ -->
      <section id="tab-colaboradores" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">👥 Colaboradores</h2>
            <button class="btn-sm btn-primary" onclick="openModal('addCollab')">
              <i class="fas fa-plus"></i> Novo Colaborador
            </button>
          </div>
          <div id="collabsTable" class="overflow-x-auto">
            <table>
              <thead><tr>
                <th>Nome</th><th>Função</th><th>Email</th><th>Status</th><th>Data Admissão</th><th>Ações</th>
              </tr></thead>
              <tbody id="collabsBody"></tbody>
            </table>
          </div>
        </div>
      </section>

      <!-- ============ INTIMAÇÕES ============ -->
      <section id="tab-intimacoes" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">🔔 Intimações</h2>
            <button class="btn-sm btn-primary" onclick="importIntimacoes()">
              <i class="fas fa-upload"></i> Importar Intimações
            </button>
          </div>
          <p class="small mb-3">Simule importação de intimações do diário oficial. Elas serão vinculadas a clientes/processos existentes ou criadas automaticamente.</p>
          <div id="intimacoesList" class="overflow-x-auto">
            <table>
              <thead><tr>
                <th>ID</th><th>Origem</th><th>Cliente/Processo</th><th>Assunto</th><th>Prazo</th><th>Status</th><th>Ações</th>
              </tr></thead>
              <tbody id="intimacoesBody"></tbody>
            </table>
          </div>
          <div id="importFeedback" class="mt-4 hidden alert alert-success"></div>
        </div>
      </section>

      <!-- ============ BACKUP ============ -->
      <section id="tab-backup" class="hidden">
        <div class="card p-5 text-center">
          <h2 class="text-xl font-bold mb-4">📦 Backup & Restauração</h2>
          <p class="small mb-6">Dados são salvos localmente via <code>localStorage</code>. O botão abaixo simula uma exportação JSON para download.</p>
          <button class="btn-primary inline-flex items-center gap-3 px-8 py-3 font-semibold" onclick="generateBackup()">
            <i class="fas fa-cloud-arrow-down"></i> Gerar Backup (.json)
          </button>
          <div id="backupFeedback" class="mt-4 hidden alert"></div>
          <div class="mt-6 card p-4">
            <h3 class="font-semibold mb-2">Estrutura dos dados salvos</h3>
            <pre class="small text-slate-400 overflow-auto max-h-32"><code>{ clients, processes, documents, appointments, transactions, tasks, collaborators, intimations, config }</code></pre>
          </div>
        </div>
      </section>

      <!-- ============ CONFIGURAÇÕES ============ -->
      <section id="tab-config" class="hidden">
        <div class="card p-5">
          <h2 class="text-xl font-bold mb-6">⚙️ Configurações do Sistema</h2>
          <form id="configForm" class="space-y-5">
            <div class="form-row">
              <div class="form-group">
                <label class="label">Nome do Escritório</label>
                <input type="text" id="cfgName" class="input-field" value="Misty Advocacia">
              </div>
              <div class="form-group">
                <label class="label">Cor Principal</label>
                <input type="color" id="cfgColor" class="input-field w-20 h-8 rounded" value="#3b82f6">
              </div>
            </div>
            <div class="form-row">
              <div class="form-group">
                <label class="label">Responsável Legal</label>
                <input type="text" id="cfgResponsible" class="input-field" value="Ana Duarte">
              </div>
              <div class="form-group">
                <label class="label">OAB</label>
                <input type="text" id="cfgOab" class="input-field" value="SP-123456">
              </div>
            </div>
            <div class="form-group">
              <label class="label">Modo de Visualização</label>
              <button type="button" class="btn-sm" onclick="toggleTheme()">
                <i class="fas fa-moon"></i> Escuro (atual)
              </button>
              <button type="button" class="btn-sm ml-2" id="themeLightBtn" onclick="toggleTheme()">
                <i class="fas fa-sun"></i> Claro
              </button>
            </div>
            <div class="form-group">
              <label class="label">Limite de Processos Ativos</label>
              <input type="number" id="cfgLimit" class="input-field" value="50" min="0">
            </div>
            <div class="form-group">
              <label class="label">Notificações Automáticas</label>
              <div class="flex gap-2">
                <button type="button" class="btn-sm bg-green-600/20 text-green-400 border border-green-600" id="notifyOn">Ativar</button>
                <button type="button" class="btn-sm bg-red-600/20 text-red-400 border border-red-600" id="notifyOff">Desativar</button>
              </div>
            </div>
            <button type="button" class="btn-primary w-full py-2" onclick="saveConfig()">Salvar Configurações</button>
          </form>
        </div>
      </section>

    </div><!-- /appContent -->
  </div><!-- /main-content -->
</main>

<!-- ================= MODAIS ================= -->

<!-- Add Client -->
<div class="modal-overlay" id="modalClient">
  <div class="modal">
    <button class="close-modal" onclick="closeModal('client')">&times;</button>
    <h2 id="mClientTitle">Novo Cliente</h2>
    <form id="formClient" onsubmit="return clientValidation(event)">
      <div class="form-row">
        <div class="form-group">
          <label class="label">Nome Completo</label>
          <input type="text" name="name" class="input-field" required>
        </div>
        <div class="form-group">
          <label class="label">CPF/CNPJ</label>
          <input type="text" name="cpf" class="input-field">
        </div>
      </div>
      <div class="form-row">
        <div class="form-group">
          <label class="label">Email</label>
          <input type="email" name="email" class="input-field" required>
        </div>
        <div class="form-group">
          <label class="label">Telefone</label>
          <input type="tel" name="phone" class="input-field">
        </div>
      </div>
      <div class="form-group">
        <label class="label">Cidade / Estado</label>
        <input type="text" name="city" class="input-field">
      </div>
      <div class="form-group">
        <label class="label">Status</label>
        <select name="status" class="input-field">
          <option value="ativo">Ativo</option>
          <option value="inativo">Inativo</option>
        </select>
      </div>
