  .btn-primary{
    background:var(--accent);color:#fff;border:none;
    padding:8px 16px;border-radius:8px;cursor:pointer;
    font-weight:600;transition:.2s;
  }
  .btn-primary:hover{opacity:.9}
  .btn-danger{
    background:transparent;color:var(--danger);border:1px solid var(--danger);
    padding:6px 12px;border-radius:6px;cursor:pointer;
    font-size:13px;transition:.2s;
  }
  .btn-danger:hover{background:rgba(239,68,68,.15);color:#fff}
  .btn-success{
    background:var(--success);color:#fff;border:none;
    padding:6px 12px;border-radius:6px;cursor:pointer;
    font-size:13px;transition:.2s;
  }
  .btn-success:hover{opacity:.9}
  .card{
    background:var(--card-bg);border:1px solid var(--border);
    border-radius:12px;padding:20px;transition:.2s;
  }
  .card:hover{border-color:rgba(59,130,246,.3)}
  table{width:100%;border-collapse:collapse;font-size:14px}
  th,td{padding:12px 14px;text-align:left;border-bottom:1px solid var(--border)}
  th{color:var(--text-muted);font-weight:600;font-size:12px;text-transform:uppercase;letter-spacing:.5px}
  tr:hover td{background:rgba(59,130,246,.06)}
  .badge{
    display:inline-block;padding:3px 9px;border-radius:20px;
    font-size:11px;font-weight:600;letter-spacing:.4px;
  }
  .badge-green{background:rgba(34,197,94,.15);color:var(--success)}
  .badge-yellow{background:rgba(245,158,11,.15);color:var(--warning)}
  .badge-red{background:rgba(239,68,68,.15);color:var(--danger)}
  .badge-blue{background:rgba(59,130,246,.15);color:var(--accent)}
  .status-col{white-space:nowrap}
  .input-field{
    width:100%;padding:10px 12px;border-radius:8px;border:1px solid var(--border);
    background:rgba(15,23,42,.6);color:var(--text);font-size:14px;
    outline:none;transition:.2s;
  }
  .input-field:focus{border-color:var(--accent);background:rgba(15,23,42,.8)}
  .form-group{margin-bottom:14px}
  .label{display:block;font-size:12px;color:var(--text-muted);margin-bottom:5px;font-weight:600}
  .form-row{display:flex;gap:12px}
  .modal-overlay{
    position:fixed;inset:0;z-index:900;background:rgba(15,23,42,.8);
    display:none;align-items:center;justify-content:center;
    animation:fade .25s ease;
  }
  .modal-overlay.open{display:flex}
  @keyframes fade{from{opacity:0}to{opacity:1}}
  .modal{
    background:#1a2740;border:1px solid var(--border);border-radius:16px;
    width:90%;max-width:640px;max-height:90vh;overflow-y:auto;
    padding:24px;position:relative;animation:slide .25s ease;
  }
  @keyframes slide{from{transform:translateY(20px)scale(.97)}to{transform:translateY(0)scale(1)}}
  .modal h2{font-size:18px;margin-bottom:18px;color:var(--accent)}
  .close-modal{
    position:absolute;top:16px right:16px;width:28px;height:28px;
    border-radius:50%;border:none;background:transparent;
    color:var(--text-muted);cursor:pointer;font-size:16px;
    transition:.2s;display:flex;align-items:center;justify-content:center;
  }
  .close-modal:hover{background:rgba(59,130,246,.2);color:var(--accent)}
  .alert{
    padding:12px 16px;border-radius:10px;margin-top:12px;
    font-size:14px;display:flex;align-items:center;gap:10px;
  }
  .alert-success{background:rgba(34,197,94,.15);border:1px solid rgba(34,197,94,.4);color:#bbf7d0}
  .alert-error{background:rgba(239,68,68,.15);border:1px solid rgba(239,68,68,.4);color:#fca5a5}
  .toast{
    position:fixed;bottom:24px;right:24px;z-index:1000;
    background:#1a2740;border:1px solid var(--accent);color:#fff;
    padding:14px 20px;border-radius:10px;transform:translateY(20px)scale(.9);
    opacity:0;transition:.3s;pointer-events:none;
  }
  .toast.show{opacity:1;transform:translateY(0)scale(1)}
  .timeline{border-left:3px solid var(--accent);padding-left:18px;margin-top:8px}
  .timeline-item{position:relative;margin-bottom:14px;padding-left:20px}
  .timeline-dot{
    position:absolute;left:-6px;top:0;width:10px;height:10px;
    border-radius:50%;background:var(--accent);
  }
  .timeline-body strong{color:var(--accent)}
  .small{font-size:12px;color:var(--text-muted)}
  .tag-pill{
    display:inline-block;padding:4px 10px;border-radius:12px;
    font-size:12px;background:rgba(59,130,246,.12);color:#93c5fd;border:1px solid rgba(59,130,246,.3);
  }
  /* Calendar mini */
  .cal-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px}
  .cal-day{
    background:var(--card-bg);border:1px solid var(--border);border-radius:8px;
    padding:10px;text-align:center;font-size:12px;cursor:pointer;
    transition:.2s;min-height:48px;
  }
  .cal-day:hover{border-color:var(--accent)}
  .cal-day.today{border-color:var(--accent);background:rgba(59,130,246,.15)}
  .cal-day.past{opacity:.5}
  .cal-day.event{background:rgba(34,197,94,.15);border-color:var(--success)}
  .cal-day.urgent{background:rgba(239,68,68,.15);border-color:var(--danger)}
  .cal-label{font-size:10px;color:var(--text-muted);margin-bottom:4px;text-transform:uppercase}
  /* Animations */
  .fade-in{animation:fadeIn .3s ease forwards}
  @keyframes fadeIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}
  /* Scrollbar */
  ::-webkit-scrollbar{width:6px}
  ::-webkit-scrollbar-track{background:transparent}
  ::-webkit-scrollbar-thumb{background:#475569;border-radius:3px}
  /* Responsive */
  @media(max-width:768px){
    .sidebar{width:100%;position:fixed;top:0;left:0;bottom:0;z-index:800}
    .sidebar.collapsed{transform:translateX(-100%)}
    .main{margin-left:0}
    .main-content{width:100%}
    .tab-bar{flex-wrap:wrap}
    .form-row{flex-direction:column}
  }
</style>
</head>
<body>

<!-- ================= SIDEBAR ================= -->
<aside class="sidebar" id="sidebar">
  <div class="sidebar-header">
    <div class="logo"><i class="fas fa-scale-balanced"></i> MI<span>S</span>SY</div>
    <span class="small" style="margin-left:auto">Escritório Digital</span>
  </div>
  <nav class="nav-links" id="navLinks">
    <div class="nav-item active" data-tab="dashboard">
      <i class="nav-icon fas fa-home"></i> Painel
    </div>
    <div class="nav-item" data-tab="clientes">
      <i class="nav-icon fas fa-user-tag"></i> Clientes
    </div>
    <div class="nav-item" data-tab="processos">
      <i class="nav-icon fas fa-file-pdf"></i> Processos
    </div>
    <div class="nav-item" data-tab="documentos">
      <i class="nav-icon fas fa-folder-open"></i> Documentos
    </div>
    <div class="nav-item" data-tab="agenda">
      <i class="nav-icon fas fa-calendar-days"></i> Agenda
    </div>
    <div class="nav-item" data-tab="financas">
      <i class="nav-icon fas fa-money-bill-alt"></i> Finanças
    </div>
    <div class="nav-item" data-tab="tarefas">
      <i class="nav-icon fas fa-check-square"></i> Tarefas
    </div>
    <div class="nav-item" data-tab="colaboradores">
      <i class="nav-icon fas fa-users"></i> Colaboradores
    </div>
    <div class="nav-item" data-tab="intimacoes">
      <i class="nav-icon fas fa-bell"></i> Intimações
    </div>
    <div class="nav-item" data-tab="backup">
      <i class="nav-icon fas fa-cloud-download"></i> Backup
    </div>
    <div class="nav-item" data-tab="config">
      <i class="nav-icon fas fa-cog"></i> Configurações
    </div>
  </nav>
  <div class="user-area">
    <div class="avatar">AD</div>
    <div>
      <div style="font-size:14px;font-weight:600">Ana Duarte</div>
      <div class="small">Sócia Gestora</div>
    </div>
  </div>
</aside>

<!-- ================= MAIN ================= -->
<main class="main">
  <div class="main-content">
    <!-- Topbar -->
    <header class="topbar">
      <div class="topbar-left">
        <button class="btn-sm" onclick="toggleSidebar()">
          <i class="fas fa-bars"></i>
        </button>
        <h2 id="pageTitle" class="fade-in">Painel Geral</h2>
      </div>
      <div class="tab-bar">
        <button class="tab active" data-tab="dashboard" onclick="switchTab('dashboard')">
          <i class="fas fa-home mr-2"></i>Painel
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="clientes" onclick="switchTab('clientes')">
          <i class="fas fa-user-tag mr-2"></i>Clientes
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="processos" onclick="switchTab('processos')">
          <i class="fas fa-file-pdf mr-2"></i>Processos
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="documentos" onclick="switchTab('documentos')">
          <i class="fas fa-folder-open mr-2"></i>Documentos
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="agenda" onclick="switchTab('agenda')">
          <i class="fas fa-calendar mr-2"></i>Agenda
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="financas" onclick="switchTab('financas')">
          <i class="fas fa-coins mr-2"></i>Finanças
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="tarefas" onclick="switchTab('tarefas')">
          <i class="fas fa-tasks mr-2"></i>Tarefas
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="colaboradores" onclick="switchTab('colaboradores')">
          <i class="fas fa-users-cogs mr-2"></i>Colaboradores
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="intimacoes" onclick="switchTab('intimacoes')">
          <i class="fas fa-envelope mr-2"></i>Intimações
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="backup" onclick="switchTab('backup')">
          <i class="fas fa-hard-platter mr-2"></i>Backup
          <span class="tab-dot"></span>
        </button>
        <button class="tab" data-tab="config" onclick="switchTab('config')">
          <i class="fas fa-settings mr-2"></i>Config
          <span class="tab-dot"></span>
        </button>
      </div>
      <div class="header-actions">
        <button class="btn-sm" onclick="openNotifications()">
          <i class="fas fa-bell"></i>
          <span id="notifCount" class="badge badge-blue" style="display:inline-block;margin-left:4px;width:18px;height:18px;text-align:center;line-height:18px">0</span>
        </button>
        <button class="btn-sm btn-primary" onclick="openModal('addClient')">
          <i class="fas fa-plus"></i> Novo Item
        </button>
        <div class="avatar" style="width:32px;height:32px">AD</div>
      </div>
    </header>

    <!-- Conteúdo dinâmico -->
    <div id="appContent" class="flex-1 overflow-auto pb-20">

      <!-- ============ DASHBOARD ============ -->
      <section id="tab-dashboard" class="fade-in space-y-6">
        <div class="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold">R$ <span id="dashTotalReceita">0,00</span></div>
                <div class="text-xs text-green-400 mt-1">↑ 12% no mês</div>
              </div>
              <i class="fas fa-dollar-sign text-2xl text-accent opacity-70"></i>
            </div>
          </div>
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold"><span id="dashTotalClientes">0</span> clientes</div>
                <div class="text-xs text-blue-400 mt-1">ativos hoje</div>
              </div>
              <i class="fas fa-users text-2xl text-accent opacity-70"></i>
            </div>
          </div>
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold"><span id="dashTotalProcessos">0</span> processos</div>
                <div class="text-xs text-yellow-400 mt-1">em andamento</div>
              </div>
              <i class="fas fa-law-contract text-2xl text-warning opacity-70"></i>
            </div>
          </div>
          <div class="card p-5">
            <div class="flex justify-between items-start">
              <div>
                <div class="text-2xl font-bold"><span id="dashPendentes">0</span> pendentes</div>
                <div class="text-xs text-red-400 mt-1">próximos 7 dias</div>
              </div>
              <i class="fas fa-clock text-2xl text-red-400 opacity-70"></i>
            </div>
          </div>
        </div>
        <div class="card p-5">
          <h3 class="text-lg font-semibold mb-4">Últimas Intimações</h3>
          <div id="dashboardRecentes" class="space-y-3 max-h-64 overflow-y-auto">
            <p class="small text-center text-text-muted">Nenhuma intimação recente.</p>
          </div>
        </div>
        <div class="card p-5">
          <h3 class="text-lg font-semibold mb-4">Atalhos Rápidos</h3>
          <div class="grid grid-cols-2 gap-3">
            <button class="btn-sm" onclick="openModal('addClient')">Novo Cliente</button>
            <button class="btn-sm" onclick="openModal('addProcess')">Novo Processo</button>
            <button class="btn-sm" onclick="importIntimacoes()">Importar Intimações</button>
            <button class="btn-sm" onclick="generateBackup()">Gerar Backup</button>
          </div>
        </div>
      </section>

      <!-- ============ CLIENTES ============ -->
      <section id="tab-clientes" class="hidden">
        <div class="card p-5">
          <div class="flex justify-between align-items-center mb-4">
            <h2 class="text-xl font-bold">🧑 Clientes</h2>
            <button class="btn-sm btn-primary" onclick="openModal('addClient')">
              <i class="fas fa-plus"></i> Novo Cliente
            </button>
          </div>

          <div class="form-row mb-4">
            <input type="text" id="searchClients" placeholder="Buscar clientes..." class="input-field w-1/3" oninput="filterClients()">
            <select id="filterStatusClients" class="input-field w-1/5">
              <option value="">Todos</option>
              <option value="ativo">Ativo</option>
              <option value="inativo">Inativo</option>
            </select>
          </div>

          <div id="clientsTable" class="overflow-x-auto">
