<!-- Toast -->
<div id="toast" class="toast"></div>

<script>
/* =========================================================
   MISSY — SISTEMA JURÍDICO COMPLETO
   ========================================================*/

// ---------- ESTADO GLOBAL (persistido em localStorage) ----------
const KEY = 'missy_v1';
let state = loadState() || {};

function loadState(){
  try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch(e){ return {}; }
}
function saveState(s){
  try{ localStorage.setItem(KEY, JSON.stringify(s)); }catch(e){}
}

// ---------- NAVEGAÇÃO DE ABAS ----------
const tabs = ['dashboard','clientes','processos','documentos','agenda','financas','tarefas','colaboradores','intimacoes','backup','config'];
let currentTab = 'dashboard';

function switchTab(tab){
  currentTab = tab;
  document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('#appContent section').forEach(s => s.classList.add('hidden'));
  const idx = tabs.indexOf(tab);
  if(idx >= 0) document.querySelectorAll('.tab')[idx].classList.add('active');
  document.getElementById('tab-'+tab).classList.remove('hidden');
  document.getElementById('pageTitle').textContent = getTabLabel(tab);
  applyFiltersForTab(tab);
}
function getTabLabel(t){
  const m={dashboard:'Painel Geral',clientes:'Clientes',processos:'Processos',documentos:'Documentos',
         agenda:'Agenda',financas:'Finanças',tarefas:'Tarefas',colaboradores:'Colaboradores',
         intimacoes:'Intimações',backup:'Backup',config:'Configurações'};
  return m[t] || t;
}
function toggleSidebar(){
  document.getElementById('sidebar').classList.toggle('collapsed');
  document.querySelector('.main').classList.toggle('margin-left', '260px');
}

// ---------- NOTIFICAÇÕES ----------
let notifications = [];
function addNotification(msg, type='info'){
  notifications.push({msg,type,time:new Date().toLocaleTimeString()});
  document.getElementById('notifCount').textContent = notifications.length;
  const el = document.createElement('div');
  el.className = `alert ${type==='error'?'alert-error':'alert-success'}`;
  el.innerHTML = `<span class="fas fa-${type==='error'?'exclamation-circle':'check-circle'} fa-lg"></span>${msg}`;
  document.getElementById('appContent').prepend(el);
  setTimeout(()=>el.style.transition='0.5s';setTimeout(()=>el.remove(),6000),200);
}

// ---------- UTILITÁRIOS ----------
const now = new Date();
function fmtDate(d){ return d.toLocaleDateString('pt-BR',{year:'numeric',month:'short',day:'numeric'}) + ' às ' + d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}); }
function fmtMoney(v){ return v>=0 ? 'R$ '+v.toFixed(2) : '-R$ '+Math.abs(v).toFixed(2); }
function randomId(prefix=''){ return prefix+'_'+Math.random().toString(36).slice(2,8); }
function pick(arr){ return arr[Math.floor(Math.random()*arr.length)]; }

// Preenche selects dinamicamente
function populateClientSelect(select){
  select.innerHTML='<option value="">Selecione...</option>';
  state.clients.forEach(c=>{
    const opt=document.createElement('option');opt.value=c.id;opt.textContent=c.name||c.cidade||'—';
    select.appendChild(opt);
  });
}
function populateProcessSelect(select){
  select.innerHTML='<option value="">Selecione...</option>';
  state.processes.filter(p=>p.clientId).forEach(p=>{
    const c=state.clients.find(x=>x.id===p.clientId);
    const opt=document.createElement('option');opt.value=p.id;opt.textContent=(c?c.name:p.clientId);
    select.appendChild(opt);
  });
}
function populateClassSelect(select){
  select.innerHTML='<option value="">Escolha...</option>';
  const cls=['Ação Trabalhista','Ação de Indenização','Execução Fiscal','Divórcio Litigioso',
             'Inventário','Habeas Corpus','Reclamação Trabalhista','Obrigação de Fazer',
             'Usucapião','Monitória','Embargos à Execução','Cumprimento de Sentença'];
  cls.forEach(c=>{const o=document.createElement('option');o.textContent=c;select.appendChild(o);});
}
function populateRoleSelect(select){
  select.innerHTML='<option value="">Escolha...</option>';
  const r=['Sócio','Advogado Júnior','Estagiário','Secretária','Analista Financeiro','Conciliador'];
  r.forEach(r2=>{const o=document.createElement('option');o.textContent=r2;select.appendChild(o);});
}

// ---------- CLIENTES ----------
function renderClients(filterStatus='',search=''){
  const tbody=document.getElementById('clientsBody');
  let html='';
  const q=search.toLowerCase();
  state.clients.forEach(c=>{
    if(filterStatus && c.status!==filterStatus) return;
    if(q && !(c.name.toLowerCase().includes(q) || c.email.toLowerCase().includes(q))) return;
    const statusBadge=c.status==='ativo'?'badge-green':'badge-red';
    html+=`
      <tr class="fade-in">
        <td><strong>${c.name}</strong><br><span class="small">${c.email}</span></td>
        <td>${c.email||'—'}</td>
        <td>${c.city||'—'}</td>
        <td><span class="${statusBadge}">${c.status.toUpperCase()}</span></td>
        <td>${fmtDate(new Date(c.dateCreated||now))}</td>
        <td>
          <button class="btn-sm" style="color:var(--accent)" onclick="editClient('${c.id}')"><i class="fas fa-edit"></i></button>
          <button class="btn-sm" style="color:var(--danger)" onclick="deleteClient('${c.id}')"><i class="fas fa-trash"></i></button>
        </td>
      </tr>`;
  });
  tbody.innerHTML=html||'<tr><td colspan="6" class="text-center small text-text-muted">Nenhum cliente encontrado.</td></tr>';
}
function deleteClient(id){
  if(!confirm('Excluir este cliente?')) return;
  state.clients=state.clients.filter(c=>c.id!==id);
  saveState();
  renderClients();
  addNotification('Cliente removido.', 'success');
}
function editClient(id){
  const c=state.clients.find(x=>x.id===id);
  if(!c) return;
  document.getElementById('editClientId').value=c.id;
  document.getElementById('ecName').value=c.name||'';
  document.getElementById('ecCpf').value=c.cpf||'';
  document.getElementById('ecEmail').value=c.email||'';
  document.getElementById('ecPhone').value=c.phone||'';
  document.getElementById('ecCity').value=c.city||'';
  document.getElementById('ecStatus').value=c.status;
  openModal('clientEdit');
}
function openModal(type){
  const ms={'client':'modalClient','clientEdit':'modalClientEdit','process':'modalProcess','processEdit':'modalProcessEdit',
            'doc':'modalDoc','docEdit':'modalDocEdit','compromisso':'modalCompromisso','compromissoEdit':'modalCompromissoEdit',
            'task':'modalTask','taskEdit':'modalTaskEdit','collab':'modalCollab','collabEdit':'modalCollabEdit',
            'import':'modalImport','backupSuccess':'modalBackupSuccess'}[type];
  if(ms) document.getElementById(ms).classList.add('open');
  else alert('Modal não implementado: '+type);
}
function closeModal(type){
  const ms={'client':'modalClient','clientEdit':'modalClientEdit','process':'modalProcess','processEdit':'modalProcessEdit',
            'doc':'modalDoc','docEdit':'modalDocEdit','compromisso':'modalCompromisso','compromissoEdit':'modalCompromissoEdit',
            'task':'modalTask','taskEdit':'modalTaskEdit','collab':'modalCollab','collabEdit':'modalCollabEdit',
            'import':'modalImport','backupSuccess':'modalBackupSuccess'}[type];
  if(ms) document.getElementById(ms).classList.remove('open');
  else location.reload();
}
function clientValidation(e){
  const f=e.target;
  let ok=true;
  const name=f.elements.namedItem('name');
  const email=f.elements.namedItem('email');
  if(!name||!name.value.trim()) { addNotification('Nome é obrigatório.','error'); ok=false; }
  if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){ addNotification('E-mail inválido.','error'); ok=false; }
  if(ok) {
    const id=randomId('cli_');
    state.clients.unshift({id,name:nome.value.trim(),email,email.value.trim(),cpf:f.elements.namedItem('cpf').value||'',phone:f.elements.namedItem('phone').value||'',city:f.elements.namedItem('city').value||'',status:f.elements.namedItem('status').value,dateCreated:new Date().toISOString()});
    saveState();
    closeModal('client');
    renderClients();
    addNotification('Cliente cadastrado com sucesso!', 'success');
    // atualiza selects
    populateClientSelect(document.querySelector('[name=clientId]'));
  }
  return ok;
}
function filterClients(){
  const s=document.getElementById('searchClients').value.toLowerCase();
  const st=document.getElementById('filterStatusClients').value;
  renderClients(st,st?'' ,s);
}

// ---------- PROCESSOS ----------
function renderProcesses(search=''){
  const tbody=document.getElementById('processesBody');
  const qs=search.toLowerCase();
  state.processes.sort((a,b)=>new Date(b.dateOpen)-new Date(a.dateOpen)).forEach(p=>{
    const c=state.clients.find(x=>x.id===p.clientId);
    const clp=p.class||'Não informado';
    const sb=p.status==='ativo'?'badge-blue':p.status==='suspenso'?'badge-yellow':'badge-red';
    if(qs && !/(^|\\b)/i.test(p.num.toLowerCase().replace(/\s/g,'')) && !(p.num.toLowerCase().includes(qs) || (c&&c.name.toLowerCase().includes(qs)))) return;
    html=`
      <tr class="fade-in">
        <td><strong>${p.num}</strong></td>
        <td>${c?'<span class="small">'+c.name+'</span>':(p.clientId?'<span class="small">ID:'+p.clientId':'—')}</td>
        <td>${clp}</td>
        <td><span class="${sb}">${p.status.toUpperCase()}</span></td>
        <td>${fmtDate(new Date(p.dateOpen||now))}</td>
        <td>${fmtMoney(p.value||0)}</td>
        <td>
          <button class="btn-sm" style="color:var(--accent)" onclick="editProcess('${p.id}')"><i class="fas fa-edit"></i></button>
          <button class="btn-sm" style="color:var(--danger)" onclick="deleteProcess('${p.id}')"><i class="fas fa-trash"></i></button>
        </td>
      </tr>`;
  });
  tbody.innerHTML=html||'<tr><td colspan="7" class="text-center small text-text-muted">Nenhum processo encontrado.</td></tr>';
}
function deleteProcess(id){
  if(!confirm('Excluir processo?')) return;
  state.processes=state.processes.filter(p=>p.id!==id);
  saveState();
  renderProcesses();
  addNotification('Processo removido.', 'success');
}
function openProcessModal(id=''){
  const isEdit=!id;
  document.getElementById('editProcId').value=isEdit?state.processes.find(p=>p.id===id)?.id:'';
  if(isEdit){
    const p=state.processes.find(x=>x.id===id);
    document.getElementById('epNum').value=p?.num||'';
    document.getElementById('epClientId').value=p?.clientId||'';
    populateClientSelect(document.getElementById('epClientId'));
    document.getElementById('epClass').value=p?.class||'';
    populateClassSelect(document.getElementById('epClass'));
    document.getElementById('epValue').value=p?.value||'';
    document.getElementById('epStatus').value=p?.status||'';
  }
  openModal(isEdit?'processEdit':'process');
}
function processValidation(e){
  const f=e.target;
  let ok=true;
  const num=f.elements.namedItem('num');
  const clientId=f.elements.namedItem('clientId');
  const classSel=f.elements.namedItem('class');
  if(!num||!num.value.trim()){ addNotification('Número do processo é obrigatório.','error'); ok=false; }
  if(!clientId||!clientId.value){ addNotification('Selecione um cliente.','error'); ok=false; }
  if(!classSel||!classSel.value){ addNotification('Selecione uma classe.','error'); ok=false; }
  if(ok){
    const id=randomId('proc_');
    const nowD=new Date().toISOString();
    const c=state.clients.find(x=>x.id===clientId.value);
    const p={id, num:num.value.trim(), clientId:clientId.value, class:classSel.value, value:(parseFloat(f.elements.namedItem('value').value)||0), status:f.elements.namedItem('status').value, dateOpen:nowD};
    state.processes.unshift(p);
    saveState();
    closeModal('process');
    renderProcesses();
    populateClientSelect(document.querySelector('[name=clientId]'));
    populateClassSelect(document.querySelector('[name=class]'));
    addNotification('Processo criado com sucesso!', 'success');
  }
  return ok;
}
function filterProcesses(){
  document.getElementById('processesBody').innerHTML='';
  renderProcesses(document.getElementById('searchProcesses').value.toLowerCase());
}

// ---------- DOCUMENTOS ----------
function renderDocs(){
  const tbody=document.getElementById('docsBody');
  state.documents.sort((a,b)=>new Date(b.date)-new Date(a.date)).forEach(d=>{
    const p=state.processes.find(x=>x.id===d.procId);
    const pr=p?'<span class="small">'+(p.num||'sem processo')+'</span>':'<span class="small">—</span>';
    html=`
      <tr class="fade-in">
        <td><strong>${d.title}</strong></td>
        <td>${d.type}</td>
        <td>${pr}</td>
        <td>${state.clients.find(c=>c.id===d.clientId)?state.clients.find(c=>c.id===d.clientId).name:'—'}</td>
        <td><span class="${d.status==='enviado'?'badge-green':d.status==='revisado'?'badge-blue':'badge-yellow'}">${d.status.toUpperCase()}</span></td>
        <td>${fmtDate(new Date(d.date))}</td>
        <td>
          <button class="btn-sm" style="color:var(--accent)" onclick="editDoc('${d.id}')"><i class="fas fa-edit"></i></button>
          <button class="btn-sm" style="color:var(--danger)" onclick="deleteDoc('${d.id}')"><i class="fas fa-trash"></i></button>
        </td>
      </tr>`;
  });
  tbody.innerHTML=html||'<tr><td colspan="7" class="text-center small text-text-muted">Nenhum documento.</td></tr>';
}
function deleteDoc(id){
  if(!confirm('Excluir documento?')) return;
  state.documents=state.documents.filter(d=>d.id!==id);
  saveState();renderDocs();addNotification('Documento removido.','success');
}
function openDocModal(id=''){
  const isEdit=!id;
  document.getElementById('editDocId').value=isEdit?state.documents.find(d=>d.id===id)?.id:'';
  if(isEdit){
    const d=state.documents.find(x=>x.id===id);
    document.getElementById('edTitle').value=d?.title||'';
    document.getElementById('edType').value=d?.type||'';
    populateTypeSelect(document.getElementById('edType'));
    document.getElementById('edProcSelect').value=d?.procId||'';
    document.getElementById('edStatus').value=d?.status||'';
    document.getElementById('edDate').value=d?.date||new Date().toISOString().split('T')[0];
  }
  openModal(isEdit?'docEdit':'doc');
}
function docValidation(e){
  const f=e.target;
  let ok=true;
  const title=f.elements.namedItem('title');
  if(!title||!title.value.trim()){ addNotification('Título é obrigatório.','error');ok=false;}
  const type=f.elements.namedItem('type');
  if(!type||!type.value){addNotification('Selecione um tipo.','error');ok=false;}
  if(ok){
    const id=randomId('doc_');
    const now=new Date().toISOString();
    const d={id,title:title.value.trim(),type:type.value, procId:f.elements.namedItem('procId').value||null,
             status:f.elements.namedItem('status').value,date:now+ (f.elements.namedItem('date').value?new Date(f.elements.namedItem('date').value).toISOString():''),
             clientId:f.elements.namedItem('clientId').value||null, desc:f.elements.namedItem('desc').value||''};
    state.documents.unshift(d);
    saveState();closeModal('doc');renderDocs();
    addNotification('Documento salvo.','success');
  }
  return ok;
}
function populateTypeSelect(sel){
  sel.innerHTML='<option value="">Escolha...</option>';
  const ts=['Petição Inicial','Contestação','Contrato','Certidão','Procuração','Decisão Judicial','Comprovante','Laudo Pericial','Recurso','Substabelecimento'];
  ts.forEach(t=>{const o=document.createElement('option');o.textContent=t;sel.appendChild(o);});
}
function filterDocs(){document.getElementById('docsBody').innerHTML='';renderDocs();}

// ---------- AGENDA ----------
function buildDayGrid(days){
  const container=document.getElementById('calGrid');
  days.forEach((d,i)=>{
    const dayOfWeek=i%7;
    const date = new Date();
    date.setDate(date.getDate()+d);
    const isToday=date.getDay()===0||true; // simplificado
    const isPast=date<new Date();
    const hasEvents=state.appointments.some(a=>{
      const ad=new Date(a.date+'T'+a.time);
      const dd=new Date(date.getFullYear(),date.getMonth(),date.getDate());
      return a.type&&ad.getTime()>=dd.getTime()&&ad.getTime()<=dd.getTime()+24*60*60*3 && (a.clientId||a.processId)? true : false;
    });
    const urgent=state.appointments.some(a=>{
      const ad=new Date(a.date+'T'+a.time);
      const due=new Date(); due.setHours(due.getHours()+24);
      return a.dueBy && ad.getTime()>due.getTime()-8*3600000;
    });
    const cls=urgent?'urgent':isPast?'past':(hasEvents?'event':'');
    const label = date.toLocaleDateString('pt-BR',{weekday:'short',month:'short',day:'numeric'});
    const evts=state.appointments.filter(a=>{
      const ad=new Date(a.date+'T'+a.time);
      const dd=new Date(date.getFullYear(),date.getMonth(),date.getDate());
      return a.type&&ad.getTime()>=dd.getTime()&&ad.getTime()<=dd.getTime()+24*60*60*3;
    }).map(a=>{const c=state.clients.find(x=>x.id===a.clientId); return `${a.type}: ${a.desc||a.clientId?state.clients.find(z=>z.id===a.clientId)?.name:''} | ${a.time}`;});
    const div=`
      <div class="${cls} ${isToday?'today':''}${isPast?' past':''}" onclick="openCompromissoPicker(${date.getTime()})">
        <div class="cal-label">${label}</div>
        <div class="font-semibold">${isToday?'HOJE':''}</div>
        ${evts.length?'<div class="text-xs mt-1 line-clamp-2">'+evts.join('<br>')+'</div>':''}
      </div>`;
    container.insertAdjacentHTML('beforeend',div);
  });
}
function setWeek(offset){
  const d=new Date(); d.setDate(d.getDate()+offset);
  const days=[...Array(7)].fill(0).map((_,i)=>new Date(d.getFullYear(),d.getMonth(),d.getDate()+i));
  buildDayGrid(days.map(x=>x.getTime()));
}
function openCompromissoPicker(timeMs){
  const target=new Date(timeMs);
  const year=target.getFullYear(), month=target.getMonth(), day=target.getDate();
  const today=new Date();
  const diffDays=Math.round((target-today.getTime())/86400000);
  if(diffDays<0){ alert('Não pode ser data passada.'); return; }
  if(diffDays>30){ alert('Máximo 30 dias para frente.'); return; }
  openModal('compromisso');
  document.getElementById('cdDate').value=target.toISOString().slice(0,10);
  // associa se possível
  const related=state.appointments.filter(a=>a.date===target.getTime()).map(a=>a.clientId||a.processId);
  if(related.length){
    document.getElementById('cdAssoc').value=related[0];
    populateClientSelect(document.getElementById('cdAssoc'));
  }
}
function compromissoValid(e){
  const f=e.target;
  let ok=true;
  const date=f.elements.namedItem('date');
  const time=f.elements.namedItem('time');
  if(!date||!date.value){addNotification('Data é obrigatória.','error');ok=false;}
  if(!time||!time.value){addNotification('Horário é obrigatório.','error');ok=false;}
  if(!ok){return;}
  const id=randomId('ap_');
  const target=new Date(date.value+'T'+time.value+':00');
  const ap={id, date:target.toISOString(), time:time.value, desc:f.elements.namedItem('desc').value||'',
            type:f.elements.namedItem('type').value, clientId:f.elements.namedItem('assoc').value||null, processId:null, dueBy:null};
  state.appointments.unshift(ap);
  saveState();closeModal('compromisso');buildDayGrid([...Array(7)].fill(0).map(i=>new Date(now.getTime()+i*86400000)));
  addNotification('Compromisso agendado.','success');
}
function editCompromisso(id){
  const a=state.appointments.find(x=>x.id===id);
  if(!a)return;
  document.getElementById('ecType').value=a.type;
  document.getElementById('ecDate').value=a.date.split('T')[0];
  document.getElementById('ecTime').value=a.time;
  document.getElementById('ecDesc').value=a.desc||'';
  if(a.clientId) populateClientSelect(document.getElementById('ecAssoc'));
  document.getElementById('ecAssoc').value=a.clientId||'';
  openModal('compromissoEdit');
}

// ---------- FINANÇAS ----------
let txs=[];
function renderTransactions(){
  const tbody=document.getElementById('transactionsBody');
  txs.sort((a,b)=>b.date-localString(a.date)).forEach(t=>{
    const clr=t.type==='entrada'?'green':'red';
    const icon=t.type==='entrada'?'fa-arrow-up':'fa-arrow-down';
    const tag=t.type==='credito'?badge-green:badge-red;
    html=`
      <tr class="fade-in">
        <td>${fmtDate(new Date(t.date))}</td>
        <td>${t.desc}</td>
        <td><span class="${tag}">${icon} ${t.type.toUpperCase()}</span></td>
        <td class="${clr} font-bold">${fmtMoney(t.amount)}</td>
        <td>${state.clients.find(c=>c.id===t.clientId)?state.clients.find(c=>c.id===t.clientId).name:t.clientId?'ID:'+t.clientId:'—'}</td>
        <td>${t.status==='pago'?'badge-green':'badge-yellow'}</td>
        <td>
          <button class="btn-sm" style="color:var(--accent)" onclick="editTx('${t.id}')"><i class="fas fa-edit"></i></button>
          <button class="btn-sm" style="color:var(--danger)" onclick="deleteTx('${t.id}')"><i class="fas fa-trash"></i></button>
        </td>
      </tr>`;
  });
  tbody.innerHTML=html||'<tr><td colspan="7" class="text-center small text-text-muted">Sem lançamentos.</td></tr>';
}
function addTransaction(){
  const f=document.getElementById('formTx');
  const desc=f.elements.namedItem('desc');
  const amount=f.elements.namedItem('amount');
  const type=f.elements.namedItem('type').value;
  let ok=true;
  if(!desc||!desc.value.trim()){addNotification('Descrição obrigatória.','error');ok=false;}
  if(!amount||isNaN(parseFloat(amount.value))||parseFloat(amount.value)<=0){addNotification('Valor inválido.','error');ok=false;}
  if(!ok)return;
  const id=randomId('tx_');
  const now=new Date().toISOString();
  const amt=parseFloat(amount.value);
  const tx={id, date:now, desc:desc.value.trim(), amount:amt, type,type:type,
            clientId:f.elements.namedItem('clientId').value||null, status:'pendente', paid:false};
  txs.unshift(tx);
  updateBalances();
  saveState();
  closeModal('finance');
  renderTransactions();
  addNotification('Lançamento adicionado.','success');
}
function showBalance(){
  const total=txs.reduce((s,t)=>s+t.amount,0);
  document.getElementById('saldoTotal').textContent=fmtMoney(total);
  document.getElementById('totalEntradas').textContent=fmtMoney(txs.filter(t=>t.type==='entrada').reduce((s,t)=>s+t.amount,0)||0);
  document.getElementById('totalSaidas').textContent=fmtMoney(Math.abs(txs.filter(t=>t.type==='saida').reduce((s,t)=>s+t.amount,0)||0));
}
function editTx(id){
  const t=txs.find(x=>x.id===id);
  if(!t)return;
  document.getElementById('etTxId').value=t.id;
  document.getElementById('edTxDesc').value=t.desc;
  document.getElementById('edTxAmount').value=t.amount;
  document.getElementById('edTxType').value=t.type;
  document.getElementById('edTxStatus').value=t.status;
  openModal('financeEdit');
}
function txValid(e){
  const f=e.target;
  let ok=true;
  const desc=f.elements.namedItem('desc');
  const amount=f.elements.namedItem('amount');
  if(!desc||!desc.value.trim()){addNotification('Descrição obrigatória.','error');ok=false;}
  if(!amount||isNaN(parseFloat(amount.value))||parseFloat(amount.value)<=0){addNotification('Valor inválido.','error');ok=false;}
  if(ok){
    const id=randomId('tx2_');
    const amt=parseFloat(amount.value);
    const now=new Date().toISOString();
    const tx={id, date:now, desc:desc.value.trim(), amount:amt, type:f.elements.namedItem('type').value,
              clientId:f.elements.namedItem('clientId').value||null, status:f.elements.namedItem('status').value||'pendente', paid:false};
    txs.unshift(tx);updateBalances();saveState();closeModal('financeEdit');renderTransactions();addNotification('Lançamento atualizado.','success');}
  return ok;
}
function deleteTx(id){
  if(!confirm('Excluir lançamento?'))return;
  txs=txs.filter(t=>t.id!==id);updateBalances();saveState();renderTransactions();addNotification('Lançamento removido.','success');
}

// ---------- TAREFAS ----------
function renderTasks(filter='all'){
  const list=document.getElementById('tasksList');
  const filtered=filter==='pendente'?state.tasks.filter(t=>!t.done):filter==='concluido'?state.tasks.filter(t=>t.done):state.tasks;
  filtered.forEach(t=>{
    const cls=t.priority==='alta'?'badge-red':t.priority==='média'?'badge-yellow':'badge-green';
    const check='<input type="checkbox" checked='+t.done+'>';
    html=`
      <div class="task-card fade-in ${t.due?''':''}">
        <div class="flex items-center justify-between">
          <span class="font-medium">${t.title}</span>
          <span class="${cls} badge">${t.priority.toUpperCase()}</span>
        </div>
        ${t.due?`<div class="text-xs mt-1 text-yellow-400"><i class="fas fa-clock"></i> Vence em ${t.dueDays}d</div>`:''}
        <div class="text-xs text-text-muted mt-1">${t.type||''}</div>
        <div class="flex justify-end mt-2 gap-2">
          <label class="inline-flex items-center gap-1">
            ${check}<input type="checkbox" onchange="toggleTask(this.parentElement.parentElement.id)">
          </label>
          <button class="btn-sm" style="color:var(--accent)" onclick="editTask('${t.id}')"><i class="fas fa-edit"></i></button>
          <button class="btn-sm" style="color:var(--danger)" onclick="deleteTask('${t.id}')"><i class="fas fa-trash"></i></button>
        </div>
      </div>`;
    list.insertAdjacentHTML('beforeend',html);
  });
  if(!list.innerHTML) list.innerHTML='<p class="small text-center text-text-muted">Nenhuma tarefa encontrada.</p>';
}
function toggleTask(cardId){
  const card=cardId.parentNode.querySelector('.task-card');
  const done=card.querySelector('input[type=checkbox]').checked;
  state.tasks=state.tasks.map(t=>t.id===card.dataset.id?t:{...t,done:done}:t);
  saveState();renderTasks();addNotification(done?'Tarefa concluída.','success':'Tarefa marcada como pendente.','info');
}
function addTask(){
  const f=document.getElementById('formTask');
  const title=f.elements.namedItem('title');
  let ok=true;
  if(!title||!title.value.trim()||title.value.trim().length<3){addNotification('Título deve ter pelo menos 3 caracteres.','error');ok=false;}
  if(ok){
    const id=randomId('tk_');
    const dueDays=f.elements.namedItem('dueDays').value||7;
    const now=new Date().toISOString();
    const dueDate=new Date(); dueDate.setDate(dueDate.getDate()+parseInt(dueDays));
    const t={id, title:title.value.trim(), priority:f.elements.namedItem('priority').value, dueDays:parseInt(dueDays), due:dueDate.toISOString(), done:false, type:f.elements.namedItem('type').value||''};
    state.tasks.unshift(t);
    saveState();closeModal('task');renderTasks();addNotification('Tarefa criada.','success');
  }
  return ok;
}
function taskValid(e){return addTask();}
function editTask(id){
  const t=state.tasks.find(x=>x.id===id);
  if(!t)return;
  document.getElementById('etTkId').value=t.id;
  document.getElementById('etTitle').value=t.title;
  document.getElementById('etPriority').value=t.priority;
  document.getElementById('etDue').value=t.due?new Date(t.due).toISOString().slice(0,10):'';
  openModal('taskEdit');
}
function deleteTask(id){
  if(!confirm('Excluir tarefa?'))return;
  state.tasks=state.tasks.filter(t=>t.id!==id);saveState();renderTasks();addNotification('Tarefa removida.','success');
}

// ---------- COLABORADORES ----------
function renderCollabs(){
  const tbody=document.getElementById('collabsBody');
  state.collaborators.sort((a,b)=>b.admission-new Date(a.admission||b.admission)).forEach(c=>{
    const sb=c.status==='ativo'?'badge-green':'badge-red';
    html=`
      <tr class="fade-in">
        <td><strong>${c.name}</strong><br><span class="small">${c.role}</span></td>
        <td>${c.role}</td>
        <td>${c.email||'—'}</td>
        <td><span class="${sb}">${c.status.toUpperCase()}</span></td>
        <td>${fmtDate(new Date(c.admission||now))}</td>
        <td>
          <button class="btn-sm" style="color:var(--accent)" onclick="editCollab('${c.id}')"><i class="fas fa-edit"></i></button>
