  });
  tbody.innerHTML=tbody.innerHTML||'<tr><td colspan="6" class="text-center small text-text-muted">Nenhum colaborador.</td></tr>';
}
function deleteCollab(id){
  if(!confirm('Excluir colaborador?'))return;
  state.collaborators=state.collaborators.filter(c=>c.id!==id);saveState();renderCollabs();addNotification('Colaborador removido.','success');
}
function openCollabModal(id=''){
  const isEdit=!id;
  document.getElementById('editCollabId').value=isEdit?state.collaborators.find(c=>c.id===id)?.id:'';
  if(isEdit){
    const c=state.collaborators.find(x=>x.id===id);
    document.getElementById('ecName2').value=c?.name||'';
    document.getElementById('ecRole').value=c?.role||'';
    populateRoleSelect(document.getElementById('ecRole'));
    document.getElementById('ecEmail2').value=c?.email||'';
    document.getElementById('ecStatus').value=c?.status||'';
    document.getElementById('ecAdm').value=c?.admission||new Date().toISOString().slice(0,10);
  }
  openModal(isEdit?'collabEdit':'collab');
}
function collabValid(e){
  const f=e.target;
  let ok=true;
  const name=f.elements.namedItem('name');
  const email=f.elements.namedItem('email');
  if(!name||!name.value.trim()){addNotification('Nome obrigatório.','error');ok=false;}
  if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){addNotification('E-mail inválido.','error');ok=false;}
  if(ok){
    const id=randomId('cb_');
    const adm=new Date(f.elements.namedItem('date').value).toISOString();
    state.collaborators.unshift({id,name:name.value.trim(),role:f.elements.namedItem('role').value,email,email.value.trim(),status:f.elements.namedItem('status').value,admission:adm});
    saveState();closeModal('collab');renderCollabs();addNotification('Colaborador cadastrado.','success');
  }
  return ok;
}

// ---------- INTIMAÇÕES ----------
let intimations=[];
function renderIntimations(){
  const tbody=document.getElementById('intimacoesBody');
  if(!intimations.length){
    tbody.innerHTML='<tr><td colspan="7" class="text-center small text-text-muted">Nenhuma intimação recebida.</td></tr>';
    return;
  }
  tbody.innerHTML='';
  intimations.slice(-12).sort((a,b)=>b.received-new Date(a.received)).forEach(i=>{
    const p=state.processes.find(x=>x.id===i.processId);
    const pname=p?'<span class="small">'+(p.clientId?state.clients.find(c=>c.id===p.clientId)?.name:p.num||'—')+'</span>':'—';
    const sb=i.status==='lida'?'badge-green':i.status==='aguardando'?'badge-blue':'badge-yellow';
    html=`
      <tr class="fade-in">
        <td>#${i.id.slice(0,3)}</td>
        <td>${i.source||'Diário Oficial'}</td>
        <td>${pname}</td>
        <td>${i.subject}</td>
        <td>${fmtDate(new Date(i.deadline))}</td>
        <td><span class="${sb}">${i.status.toUpperCase()}</span></td>
        <td>
          <button class="btn-sm" style="color:var(--accent)" onclick="markRead('${i.id}')"><i class="fas fa-eye"></i></button>
          <button class="btn-sm" style="color:var(--danger)" onclick="deleteIntimation('${i.id}')"><i class="fas fa-trash"></i></button>
        </td>
      </tr>`;
    tbody.innerHTML+=html;
  });
}
function importIntimacoes(){
  const fb=document.getElementById('importFeedback');
  fb.className='alert';
  const kw=document.getElementById('impKeyword').value.toLowerCase();
  const sample=[
    {id:'INT_'+Math.random().toString(36).slice(2,6), source:'DJEN', subject:`Julgamento marcado - ${kw||'Processo aleatório'}`, deadline:new Date(Date.now()+8*86400000).toISOString(), status:'aguardando', processId:randomId('ip_'), relatedClientId:'', description:'Intimação de sentença publicada.'},
    {id:'INT_'+Math.random().toString(36).slice(2,6)+1, source:'DJEN', subject:`Prazo para manifestação - ${kw||'Cliente X'}`, deadline:new Date(Date.now()+3*86400000).toISOString(), status:'aguardando', processId:randomId('ip_1'), relatedClientId:'', description:'Abertura de prazo de 5 dias úteis.'},
    {id:'INT_'+Math.random().toString(36).slice(2,6)+2, source:'PJe', subject:`Despacho determinando emenda inicial`, deadline:new Date(Date.now()+2*86400000).toISOString(), status:'nova', processId:randomId('ip_2'), relatedClientId:'', description:'Juiz determinou correção da petição inicial.'}
  ];
  // vincular a clientes/processos existentes quando possível
  sample.forEach(s=>{
    const existingClients=state.clients.map(c=>c.id);
    const existingProcesses=state.processes.map(p=>p.id);
    s.processId=existingProcesses.length?pick(existingProcesses):s.processId;
    if(s.processId){
      const p=state.processes.find(x=>x.id===s.processId);
      if(!p){
        // cria processo temporário apenas para vínculo
        const temp={id:s.processId, num:'Temp_'+Math.random().toString(36).slice(2,6), clientId:pick(state.clients)||null, class:'Outros', value:0, status:'ativo', dateOpen:new Date().toISOString()};
        state.processes.push(temp);
        // limpa depois? não, mantemos para vínculo
      }
    }
  });
  intimations= [...intimations,...sample];
  saveState();
  renderIntimations();
  fb.innerHTML='<span class="fas fa-check-circle text-success fa-lg"></span><strong>Importação concluída!</strong><br>'+sample.map(s=>`• ${s.subject}`).join('<br>');
  fb.classList.remove('hidden');
  setTimeout(()=>fb.classList.add('hidden'),5000);
}
function markRead(id){
  const i=intimations.find(x=>x.id===id);
  if(!i)return;
  i.status='lida';
  saveState();renderIntimations();addNotification('Intimação marcada como lida.','success');
}
function deleteIntimation(id){
  if(!confirm('Excluir intimação?'))return;
  intimations=intimations.filter(i=>i.id!==id);saveState();renderIntimations();addNotification('Intimação removida.','success');
}

// ---------- BACKUP ----------
function generateBackup(){
  const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});
  const url=url.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url; a.download='missy-backup-'+new Date().toISOString().slice(0,10)+'.json'; a.click();
  url.releaseObject();
  addNotification('Backup gerado com sucesso!','success');
}
function downloadBackup(){
  try{
    const ls=localStorage.getItem(KEY);
    if(!ls){ throw new Error('sem-dados'); }
    const b=new Blob([ls],{type:'application/json'});
    const u=url.createObjectURL(b);
    const a=document.createElement('a');a.href=u;a.download='missy-restaurado-'+new Date().toISOString().slice(0,10)+'.json';a.click();u.releaseObject();
    addNotification('Arquivo restaurado baixado com sucesso!','success');
  }catch(err){
    addNotification('Falha ao restaurar. Verifique se há dados salvos.','error');
  }
}

// ---------- CONFIG ----------
function saveConfig(){
  const name=document.getElementById('cfgName').value;
  const resp=document.getElementById('cfgResponsible').value;
  const oab=document.getElementById('cfgOab').value;
  state.config={
    officeName:name, primaryColor:document.getElementById('cfgColor').value,
    responsible:resp, oab:oab,
    maxActiveProcesses:parseInt(document.getElementById('cfgLimit').value)||50,
    autoNotifications:document.getElementById('notifyOn').textContent==='Ativar'
  };
  // aplica tema se necessário
  applyTheme();
  saveState();
  addNotification('Configurações salvas com sucesso!','success');
}
function toggleTheme(){
  const isDark=localStorage.getItem('missyTheme')==='light';
  const root=document.documentElement;
  if(isDark){
    root.removeAttribute('data-theme-light');
    localStorage.setItem('missyTheme','dark');
    document.getElementById('themeLightBtn').textContent='<i class="fas fa-moon"></i> Escuro';
  }else{
    root.setAttribute('data-theme-light','1');
    localStorage.setItem('missyTheme','light');
    document.getElementById('themeLightBtn').textContent='<i class="fas fa-sun"></i> Claro';
  }
  applyFiltersForTab(currentTab);
}
function applyTheme(){
  const t=localStorage.getItem('missyTheme')||'dark';
  const root=document.documentElement;
  if(t==='light'){root.setAttribute('data-theme-light','1');}
  else root.removeAttribute('data-theme-light');
}

// ---------- DASHBOARD ----------
function refreshDashboard(){
  document.getElementById('dashTotalReceita').textContent=fmtMoney(txs.reduce((s,t)=>s+(t.amount||0),0));
  document.getElementById('dashTotalClientes').textContent=state.clients.length;
  document.getElementById('dashTotalProcessos').textContent=state.processes.length;
  const pendings=state.appointments.filter(a=>{
    const d=new Date(a.date+'T'+a.time);
    const nowD=new Date();
    return d>nowD && !state.appointments.find(x=>x.id===a.id&&x.completed);
  }).length;
  document.getElementById('dashPendentes').textContent=pendings;
  renderRecentIntimations();
}
function renderRecentIntimations(){
  const list=document.getElementById('dashboardRecentes');
  const recent=intimations.slice(-4).reverse();
  if(!recent.length){ list.innerHTML='<p class="small text-center text-text-muted">Nenhuma intimação recente.</p>'; return; }
  list.innerHTML='';
  recent.forEach(i=>{
    const p=state.processes.find(x=>x.id===i.processId);
    const pname=p?('<span class="small">'+(p.clientId?state.clients.find(c=>c.id===p.clientId)?.name:p.num||'—')+'</span>'):('—');
    list.innerHTML+=`
      <div class="flex justify-between items-start p-3 bg-slate-800/40 rounded-lg">
        <div>
          <div class="font-medium text-sm">${i.subject}</div>
          <div class="text-xs text-text-muted">${pname} • ${i.source}</div>
        </div>
        <span class="text-xs ${i.status==='lida'?'badge-green':i.status==='aguardando'?'badge-blue':'badge-yellow'}">${i.status.toUpperCase()}</span>
      </div>`;
  });
}

